    coords: [-92.0667, 14.9167],
    name: { de: "Malacatán", hu: "Malacatán", ro: "Malacatán", en: "Malacatán" },
    description: { de: "Wichtige Grenzstadt zu Mexiko im Departement San Marcos.", hu: "Fontos határváros Mexikóval, San Marcos megyében.", ro: "Oraș de frontieră important cu Mexic, în departamentul San Marcos.", en: "Important border town with Mexico in the San Marcos department." },
    facts: { de: ["Grenzübergang nach Mexiko", "Lebhafter Handel", "Heißes, tropisches Klima"], hu: ["Határátkelő Mexikóba", "Élénk kereskedelem", "Forró, trópusi éghajlat"], ro: ["Punct de trecere a frontierei cu Mexic", "Comerț plin de viață", "Climă caldă și tropicală"], en: ["Border crossing to Mexico", "Bustling trade", "Hot, tropical climate"] },
    descriptionAdvanced: { de: "Malacatán ist eine pulsierende Grenzstadt im Departement San Marcos, nur wenige Kilometer von der mexikanischen Grenze entfernt. Aufgrund ihrer Lage ist die Stadt ein überaus wichtiges Handelszentrum für den Austausch von Waren zwischen Guatemala und Mexiko. In Malacatán herrscht ein heißes, tropisches Klima, das den Anbau von Kaffee, Bananen und Kakao in der umliegenden Region begünstigt. Die Stadt ist geprägt von einer dynamischen Atmosphäre, geschäftigen Märkten und einem stetigen Strom von Reisenden. Als logistischer Knotenpunkt verfügt Malacatán über zahlreiche Dienstleistungsbetriebe und Transportunternehmen.", hu: "Malacatán egy lüktető határváros San Marcos megyében, mindössze néhány kilométerre a mexikói határtól. Elhelyezkedése révén a város rendkívül fontos kereskedelmi központ a Guatemala és Mexikó közötti árucsere-forgalomban. Malacatánban forró, trópusi éghajlat uralkodik, ami kedvez a kávé, a banán és a kakaó termesztésének a környező régióban. A várost dinamikus légkör, nyüzsgő piacok és az utazók folyamatos áramlása jellemzi. Logisztikai csomópontként Malacatán számos szolgáltató egységgel és szállítmányozási vállalattal rendelkezik.", ro: "", en: "Malacatán ist eine pulsierende Grenzstadt im Departement San Marcos, nur wenige Kilometer von der mexikanischen Grenze entfernt. Aufgrund ihrer Lage ist die Stadt ein überaus wichtiges Handelszentrum für den Austausch von Waren zwischen Guatemala und Mexiko. In Malacatán herrscht ein heißes, tropisches Klima, das den Anbau von Kaffee, Bananen und Kakao in der umliegenden Region begünstigt. Die Stadt ist geprägt von einer dynamischen Atmosphäre, geschäftigen Märkten und einem stetigen Strom von Reisenden. Als logistischer Knotenpunkt verfügt Malacatán über zahlreiche Dienstleistungsbetriebe und Transportunternehmen." },
    factsAdvanced: { de: ["Malacatán ist einer der wichtigsten Grenzübergänge zwischen Guatemala und Mexiko.", "Die Stadt ist ein zentraler Umschlagplatz für den legalen und informellen Grenzhandel.", "Die Wirtschaft wird durch die exportorientierte Landwirtschaft und den Handel bestimmt.", "Das Klima in der Stadt ist ganzjährig tropisch heiß."], hu: ["Malacatán ist einer der wichtigsten Grenzübergänge zwischen Guatemala und Mexiko.", "Die Stadt ist ein zentraler Umschlagplatz für den legalen und informellen Grenzhandel.", "Die Wirtschaft wird durch die exportorientierte Landwirtschaft und den Handel bestimmt.", "Das Klima in der Stadt ist ganzjährig tropisch heiß."], ro: [], en: ["Malacatán ist einer der wichtigsten Grenzübergänge zwischen Guatemala und Mexiko.", "Die Stadt ist ein zentraler Umschlagplatz für den legalen und informellen Grenzhandel.", "The economy is determined by export-oriented agriculture and trade.", "The climate in the city is tropically hot all year round."] }
