    coords: [-90.1833, 14.1000],
    name: { de: "Chiquimulilla", hu: "Chiquimulilla", ro: "Chiquimulilla", en: "Chiquimulilla" },
    description: { de: "Die größte Stadt im Departement Santa Rosa.", hu: "Santa Rosa megye legnagyobb városa.", ro: "Cel mai mare oraș din departamentul Santa Rosa.", en: "The largest city in the Santa Rosa department." },
    facts: { de: ["Handelszentrum für die Küstenregion", "Viehzucht und Landwirtschaft", "Nähe zu den Pazifikstränden"], hu: ["A partvidéki régió kereskedelmi központja", "Állattenyésztés és mezőgazdaság", "Közel a Csendes-óceán strandjaihoz"], ro: ["Centru comercial pentru regiunea de coastă", "Creșterea vitelor și agricultură", "Aproape de plajele Pacificului"], en: ["Commercial hub for the coastal region", "Cattle ranching and agriculture", "Close to Pacific beaches"] },
    descriptionAdvanced: { de: "Chiquimulilla ist die größte und wirtschaftlich bedeutendste Stadt im Departement Santa Rosa. Sie liegt verkehrsgünstig an der pazifischen Küstenstraße und dient als zentraler Handelsknotenpunkt für den Südosten Guatemalas. Die Wirtschaft der Stadt wird durch die Viehzucht und den großflächigen Anbau von Zuckerrohr und tropischen Früchten dominiert. Chiquimulilla verfügt über eine gut entwickelte Infrastruktur mit zahlreichen Handelsbetrieben, Schulen und Dienstleistungen. Die Nähe zu den Stränden des Pazifiks macht die Stadt zudem zu einem wichtigen Durchgangsort für den Tourismus. Kulturell ist die Region durch eine Mischung aus ländlichen Traditionen und der dynamischen Entwicklung einer modernen Handelsstadt geprägt.", hu: "", ro: "", en: "Chiquimulilla ist die größte und wirtschaftlich bedeutendste Stadt im Departement Santa Rosa. Sie liegt verkehrsgünstig an der pazifischen Küstenstraße und dient als zentraler Handelsknotenpunkt für den Südosten Guatemalas. Die Wirtschaft der Stadt wird durch die Viehzucht und den großflächigen Anbau von Zuckerrohr und tropischen Früchten dominiert. Chiquimulilla verfügt über eine gut entwickelte Infrastruktur mit zahlreichen Handelsbetrieben, Schulen und Dienstleistungen. Die Nähe zu den Stränden des Pazifiks macht die Stadt zudem zu einem wichtigen Durchgangsort für den Tourismus. Kulturell ist die Region durch eine Mischung aus ländlichen Traditionen und der dynamischen Entwicklung einer modernen Handelsstadt geprägt." },
    factsAdvanced: { de: ["Chiquimulilla ist das wirtschaftliche Kraftzentrum des Departements Santa Rosa.", "Die Stadt ist ein führender Standort für die Viehwirtschaft in Guatemala.", "Sie liegt an einer strategisch wichtigen Verkehrsader zur Pazifikküste.", "Zahlreiche Märkte und Handelszentren prägen das geschäftige Stadtbild."], hu: [], ro: [], en: ["Chiquimulilla ist das wirtschaftliche Kraftzentrum des Departements Santa Rosa.", "Die Stadt ist ein führender Standort für die Viehwirtschaft in Guatemala.", "It is located on a strategically important artery to the Pacific coast.", "Zahlreiche Märkte und Handelszentren prägen das geschäftige Stadtbild."] }
